// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/** The features as a grid of cards, tiles or bordered cells (the body of FeatureGrid). Icons are Lucide names. */
import { For, type JSX } from "solid-js";
import { Card, CardContent, CardHeader, CardTitle, Grid, Group, IconBadge, Stack, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { defaults } from "../presets/defaults";
import { cn } from "../utils";
import type { Feature } from "../blocks/feature-grid.types";

export type FeatureCardsProps = {
  features: Feature[];
  cols?: "1-2" | "1-3" | "1-4";
  item?: "card" | "tile" | "cell";
};

export function FeatureCards({ features, cols = "1-3", item = "card" }: FeatureCardsProps) {
  return (
    <Grid
      cols={cols}
      class={
        (item as string) === "cell" ? cn("w-full gap-px overflow-hidden bg-border p-px", defaults.features.cells)
        : "gap-6"
      }
      data-slot="feature-grid"
    >
      <For each={features ?? []}>{(feature) => (
        <>
          {((item as string) === "tile") ? (
            <Card variant="compact">
              <Group gap="4" align="start">
                <LucideIcon name={feature.icon} size={20} />
                <Stack gap="2">
                  <Title as={3} size="base" weight="bold">
                    {feature.title}
                  </Title>
                  <Text size="sm" class="text-muted-foreground">
                    {feature.text}
                  </Text>
                </Stack>
              </Group>
            </Card>
          ) : ((item as string) === "cell") ? (
            <Stack
              gap="2"
              align="center"
              class="h-full gap-8 bg-background px-6 py-12 text-center"
              data-slot="feature-card"
            >
              <IconBadge variant="primary" size="xl" data-slot="feature-icon">
                <LucideIcon name={feature.icon} size={24} />
              </IconBadge>
              <Title as={3} size="xl" weight="semibold" class="leading-6">
                {feature.title}
              </Title>
              <Text size="sm" weight="semibold" class="leading-5 text-muted-foreground">
                {feature.text}
              </Text>
            </Stack>
          ) : (
            <Card variant="default">
              <CardHeader class="flex flex-col gap-4">
                <LucideIcon name={feature.icon} size={24} />
                <CardTitle as={3}>
                  {feature.title}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <Text size="sm" class="text-muted-foreground">
                  {feature.text}
                </Text>
              </CardContent>
            </Card>
          )}
        </>
      )}</For>
    </Grid>
  );
}
